public abstract record Expr;
public sealed record Num(int Value) : Expr;
public sealed record Add(Expr Left, Expr Right) : Expr;
public static int Eval(Expr e) => e switch {
    Num(var v) => v,
    Add(var l, var r) => Eval(l) + Eval(r),
    _ => throw new InvalidOperationException($"unhandled node {e.GetType().Name}")
};

